-- projects / workorders / workorder_rows: the operational hierarchy almost
-- every satellite hangs off of.
CREATE TABLE mesh.projects (
    id           serial       PRIMARY KEY,
    code         text         UNIQUE NOT NULL,
    name         text         NOT NULL,
    status       text         NOT NULL DEFAULT 'active',
    created_at   timestamptz  NOT NULL DEFAULT now(),
    created_by   integer      REFERENCES mesh.users (id),
    changed_at   timestamptz  NOT NULL DEFAULT now(),
    changed_by   integer      REFERENCES mesh.users (id)
);

