CREATE TABLE mesh.workorders (
    id           serial       PRIMARY KEY,
    project_id   integer      NOT NULL REFERENCES mesh.projects (id),
    number       text         UNIQUE NOT NULL,
    description  text,
    status       text         NOT NULL DEFAULT 'open',
    created_at   timestamptz  NOT NULL DEFAULT now(),
    created_by   integer      REFERENCES mesh.users (id),
    changed_at   timestamptz  NOT NULL DEFAULT now(),
    changed_by   integer      REFERENCES mesh.users (id)
);

