-- qa_status_history: level 4, references proc_material, plan_document, crm_resource
CREATE TABLE mesh.qa_status_history (
    id                serial       PRIMARY KEY,
    code              varchar(24),
    title             text,
    amount            numeric(14, 2),
    quantity          integer,
    project_id        integer      REFERENCES mesh.projects (id),
    workorder_id      integer      REFERENCES mesh.workorders (id),
    workorder_row_id  integer      REFERENCES mesh.workorder_rows (id),
    proc_material_id integer      REFERENCES mesh.proc_material (id),
    plan_document_id integer      REFERENCES mesh.plan_document (id),
    crm_resource_id  integer      REFERENCES mesh.crm_resource (id),
    created_at        timestamptz  NOT NULL DEFAULT now(),
    created_by        integer      NOT NULL REFERENCES mesh.users (id),
    changed_at        timestamptz  NOT NULL DEFAULT now(),
    changed_by        integer      NOT NULL REFERENCES mesh.users (id)
);

