-- A view per satellite plus cross-satellite summaries, the way views
-- accrete in a long-lived database -- and enough of them to put the view
-- count on par with the table count.

CREATE VIEW mesh.v_asset_account AS
    SELECT s.id, s.created_at, s.changed_at,
           cu.username  AS created_by,
           chu.username AS changed_by,
           p.code       AS project_code,
           w.number     AS workorder_number
    FROM mesh.asset_account s
    LEFT JOIN mesh.users cu      ON cu.id  = s.created_by
    LEFT JOIN mesh.users chu     ON chu.id = s.changed_by
    LEFT JOIN mesh.projects p    ON p.id   = s.project_id
    LEFT JOIN mesh.workorders w  ON w.id   = s.workorder_id;

