           p.code       AS project_code,
           w.number     AS workorder_number
    FROM mesh.asset_status_history s
    LEFT JOIN mesh.users cu      ON cu.id  = s.created_by
    LEFT JOIN mesh.users chu     ON chu.id = s.changed_by
    LEFT JOIN mesh.projects p    ON p.id   = s.project_id
    LEFT JOIN mesh.workorders w  ON w.id   = s.workorder_id;

