CREATE VIEW mesh.summary_00 AS
    SELECT p.code AS project_code,
           count(DISTINCT a.id) AS asset_account_count,
           count(DISTINCT b.id) AS core_account_count
    FROM mesh.projects p
    LEFT JOIN mesh.asset_account a ON a.project_id = p.id
    LEFT JOIN mesh.core_account b ON b.project_id = p.id
    GROUP BY p.code;

CREATE VIEW mesh.summary_01 AS
    SELECT p.code AS project_code,
           count(DISTINCT a.id) AS crm_account_count,
           count(DISTINCT b.id) AS doc_account_count
    FROM mesh.projects p
    LEFT JOIN mesh.crm_account a ON a.project_id = p.id
    LEFT JOIN mesh.doc_account b ON b.project_id = p.id
    GROUP BY p.code;

CREATE VIEW mesh.summary_02 AS
    SELECT p.code AS project_code,
           count(DISTINCT a.id) AS fin_account_count,
           count(DISTINCT b.id) AS ops_account_count
    FROM mesh.projects p
    LEFT JOIN mesh.fin_account a ON a.project_id = p.id
    LEFT JOIN mesh.ops_account b ON b.project_id = p.id
    GROUP BY p.code;

CREATE VIEW mesh.summary_03 AS
    SELECT p.code AS project_code,
           count(DISTINCT a.id) AS plan_account_count,
           count(DISTINCT b.id) AS proc_account_count
    FROM mesh.projects p
    LEFT JOIN mesh.plan_account a ON a.project_id = p.id
    LEFT JOIN mesh.proc_account b ON b.project_id = p.id
    GROUP BY p.code;

CREATE VIEW mesh.summary_04 AS
    SELECT p.code AS project_code,
           count(DISTINCT a.id) AS qa_account_count,
           count(DISTINCT b.id) AS sched_account_count
    FROM mesh.projects p
    LEFT JOIN mesh.qa_account a ON a.project_id = p.id
    LEFT JOIN mesh.sched_account b ON b.project_id = p.id
    GROUP BY p.code;

